// ppte-visual-editor.js — in-place visual editing for PPTE slides.
//
// Architecture: edits made inside the live iframe are recorded as ops
// ({path, type, ...}), and slide.html is regenerated by replaying those ops on
// a clean DOMParser parse of the original HTML. The live document is never
// serialized back, so the injected <base> tag, selection outlines and script
// runtime state (e.g. stepped-animation final state) never reach the file.
window.PpteVisualEditor = {
  session: null,
  maxStepGuard: 50,

  // ---------- pure helpers (unit-testable) ----------

  encodePath(indices) {
    return (indices || []).join('/');
  },

  decodePath(path) {
    if (path === '' || path == null) return [];
    return String(path)
      .split('/')
      .map(s => parseInt(s, 10))
      .filter(n => Number.isFinite(n) && n >= 0);
  },

  // Element address: element-child index chain from <body> ("0/2/1").
  buildElementPath(el) {
    if (!el || !el.ownerDocument || !el.ownerDocument.body) return '';
    const body = el.ownerDocument.body;
    if (el === body) return '';
    const indices = [];
    let node = el;
    while (node && node !== body) {
      const parent = node.parentElement;
      if (!parent) return '';
      indices.unshift(Array.prototype.indexOf.call(parent.children, node));
      node = parent;
    }
    if (node !== body) return '';
    return this.encodePath(indices);
  },

  resolveElementPath(doc, path) {
    if (!doc || !doc.body) return null;
    let node = doc.body;
    for (const index of this.decodePath(path)) {
      if (!node.children || index >= node.children.length) return null;
      node = node.children[index];
    }
    return node === doc.body ? null : node;
  },

  // Insert parents may be <body> itself, which has the empty path.
  _resolveInsertParent(doc, parentPath) {
    if (!doc || !doc.body) return null;
    if (parentPath === '' || parentPath == null) return doc.body;
    return this.resolveElementPath(doc, parentPath);
  },

  // Merge an op into the list, keeping only the latest op per (path,type[,name]).
  mergeOp(ops, op) {
    const next = (ops || []).slice();
    if (op.type === 'remove') {
      // Removing an element invalidates every earlier op on it or its descendants.
      const prefix = op.path + '/';
      for (let i = next.length - 1; i >= 0; i--) {
        const existing = next[i];
        const p = existing.type === 'insert' ? existing.parentPath : existing.path;
        if (p === op.path || (p && p.startsWith(prefix))) next.splice(i, 1);
      }
      next.push(op);
      return next;
    }
    if (op.type !== 'insert') {
      const matches = (o) => o.type === op.type && o.path === op.path && (o.name || '') === (op.name || '');
      for (let i = next.length - 1; i >= 0; i--) {
        if (next[i].type !== 'insert' && matches(next[i])) next.splice(i, 1);
      }
    }
    next.push(op);
    return next;
  },

  // Replay ops on a clean parse of the original HTML. Returns {html, failed}.
  replayOps(baseHtml, ops) {
    const parser = new DOMParser();
    const doc = parser.parseFromString(String(baseHtml || ''), 'text/html');
    let failed = 0;
    for (const op of (ops || [])) {
      try {
        if (op.type === 'html') {
          const el = this.resolveElementPath(doc, op.path);
          if (!el) { failed += 1; continue; }
          el.innerHTML = op.html;
        } else if (op.type === 'style') {
          const el = this.resolveElementPath(doc, op.path);
          if (!el) { failed += 1; continue; }
          if (op.value === '' || op.value == null) el.style.removeProperty(op.name);
          else el.style.setProperty(op.name, String(op.value));
        } else if (op.type === 'remove') {
          const el = this.resolveElementPath(doc, op.path);
          if (!el) { failed += 1; continue; }
          el.parentNode.removeChild(el);
        } else if (op.type === 'insert') {
          const parent = this._resolveInsertParent(doc, op.parentPath);
          if (!parent) { failed += 1; continue; }
          const tpl = doc.createElement('template');
          tpl.innerHTML = op.html;
          const node = tpl.content.firstElementChild;
          if (!node) { failed += 1; continue; }
          const ref = parent.children[op.index] || null;
          parent.insertBefore(node, ref);
        }
      } catch (e) {
        failed += 1;
      }
    }
    const doctype = doc.doctype ? `<!DOCTYPE ${doc.doctype.name}>` : '<!DOCTYPE html>';
    return { html: `${doctype}\n${doc.documentElement.outerHTML}`, failed };
  },

  // Inject/replace <base href> so relative resources resolve inside srcdoc.
  injectBaseHref(html, baseUrl) {
    const safeUrl = String(baseUrl || '').replace(/&/g, '&amp;').replace(/"/g, '&quot;');
    const base = `<base href="${safeUrl}">`;
    const content = String(html || '');
    if (/<base\b[^>]*>/i.test(content)) {
      return content.replace(/<base\b[^>]*>/i, base);
    }
    if (/<head[^>]*>/i.test(content)) {
      return content.replace(/<head([^>]*)>/i, `<head$1>${base}`);
    }
    return `${base}${content}`;
  },

  // Stepped templates (data-step/data-max-step contract), mirrors the exporter.
  getStepState(doc) {
    if (!doc || typeof doc.querySelector !== 'function') return { step: 0, maxStep: 0 };
    const root = doc.querySelector('[data-template],[data-ppte-concept-animation]');
    if (!root || !root.dataset) return { step: 0, maxStep: 0 };
    const parse = value => {
      const num = parseInt(value, 10);
      return Number.isFinite(num) && num > 0 ? num : 0;
    };
    return {
      step: parse(root.dataset.step),
      maxStep: parse(root.dataset.maxStep),
    };
  },

  // Returns true when the slide consumed the key press (advanced one step).
  advanceStep(doc, win) {
    const before = this.getStepState(doc).step;
    const event = new win.KeyboardEvent('keydown', {
      key: 'ArrowRight',
      bubbles: true,
      cancelable: true,
    });
    doc.dispatchEvent(event);
    return !!event.defaultPrevented || this.getStepState(doc).step !== before;
  },

  driveToFinalStep(doc, win) {
    for (let i = 0; i < this.maxStepGuard; i++) {
      if (!this.advanceStep(doc, win)) break;
    }
  },

  _rgbToHex(value) {
    const m = String(value || '').match(/rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/i);
    if (!m) return '#000000';
    const hex = n => Number(n).toString(16).padStart(2, '0');
    return `#${hex(m[1])}${hex(m[2])}${hex(m[3])}`;
  },

  // ---------- session management ----------

  _slideBaseUrl(folderPath) {
    const dir = String(folderPath || '').replace(/\\/g, '/').replace(/\/+$/, '') + '/';
    const viewer = window.PptExtraViewer;
    if (viewer && typeof viewer._assetUrl === 'function') {
      return viewer._assetUrl(dir);
    }
    const encoded = dir.replace(/^\/+/, '').split('/').map(s => encodeURIComponent(s)).join('/');
    return 'slide://localhost/' + encoded;
  },

  openSession(options) {
    this.closeSession();
    const container = options.container;
    if (!container) return null;
    const $ = (sel) => container.querySelector(sel);
    const session = {
      container,
      folderPath: options.folderPath || '',
      readOnly: !!options.readOnly,
      onCommit: options.onCommit || null,
      onToast: options.onToast || null,
      baseHtml: String(options.html || ''),
      ops: [],
      iframe: $('#ppte-visual-iframe'),
      doc: null,
      selectedEl: null,
      editingEl: null,
      editingOriginalHtml: '',
      dragging: false,
      moved: false,
      dragStartX: 0,
      dragStartY: 0,
      startLeft: 0,
      startTop: 0,
      syncing: false,
      handlers: null,
      refs: {
        banner: $('#ppte-visual-banner'),
        addText: $('#ppte-vis-add-text'),
        addImage: $('#ppte-vis-add-image'),
        remove: $('#ppte-vis-remove'),
        undo: $('#ppte-vis-undo'),
        selectedLabel: $('#ppte-vis-selected'),
        inputs: {
          left: $('#ppte-vis-x'),
          top: $('#ppte-vis-y'),
          width: $('#ppte-vis-w'),
          height: $('#ppte-vis-h'),
          fontSize: $('#ppte-vis-font-size'),
          color: $('#ppte-vis-color'),
          bold: $('#ppte-vis-bold'),
          align: $('#ppte-vis-align'),
        },
      },
    };
    this.session = session;
    this._bindChrome(session);
    this._setReadOnly(session, session.readOnly);
    this._syncUndoState(session);
    this._loadLive(session, session.baseHtml);
    return session;
  },

  closeSession() {
    const session = this.session;
    if (!session) return;
    this._endTextEdit(session, true);
    if (session.handlers && session.doc) {
      const doc = session.doc;
      doc.removeEventListener('click', session.handlers.click, true);
      doc.removeEventListener('dblclick', session.handlers.dblclick, true);
      doc.removeEventListener('mousedown', session.handlers.mousedown, true);
      doc.removeEventListener('mousemove', session.handlers.mousemove, true);
      doc.removeEventListener('mouseup', session.handlers.mouseup, true);
      doc.removeEventListener('keydown', session.handlers.keydown, true);
    }
    if (session.iframe) {
      session.iframe.removeAttribute('srcdoc');
    }
    this.session = null;
  },

  // External change (folder watch) replaced the slide HTML: rebase the session.
  rebaseSession(html) {
    const session = this.session;
    if (!session) return;
    session.baseHtml = String(html || '');
    session.ops = [];
    this._syncUndoState(session);
    this._loadLive(session, session.baseHtml);
  },

  _toast(session, message, isError) {
    if (typeof session.onToast === 'function') session.onToast(message, isError);
  },

  _setReadOnly(session, readOnly) {
    const { addText, addImage, remove, undo, inputs } = session.refs;
    [addText, addImage, remove].forEach(btn => { if (btn) btn.disabled = readOnly; });
    Object.values(inputs).forEach(input => { if (input) input.disabled = readOnly; });
    if (undo) undo.disabled = true;
    session.container.classList.toggle('ppte-visual-readonly', readOnly);
  },

  _syncUndoState(session) {
    const undo = session.refs.undo;
    if (undo) undo.disabled = session.readOnly || session.ops.length === 0;
  },

  // ---------- live iframe ----------

  _loadLive(session, html) {
    const iframe = session.iframe;
    if (!iframe) return;
    session.selectedEl = null;
    session.editingEl = null;
    session.dragging = false;
    const srcdoc = this.injectBaseHref(html, this._slideBaseUrl(session.folderPath));
    iframe.addEventListener('load', () => this._onLiveLoad(session), { once: true });
    iframe.srcdoc = srcdoc;
  },

  _onLiveLoad(session) {
    if (this.session !== session) return;
    const doc = session.iframe.contentDocument;
    if (!doc) return;
    session.doc = doc;

    const { maxStep } = this.getStepState(doc);
    if (maxStep > 0 && doc.defaultView) {
      // Editing happens at the final state; replay is based on the original
      // HTML, so template step logic in the saved file stays intact.
      this.driveToFinalStep(doc, doc.defaultView);
      session.refs.banner?.classList.remove('hidden');
    } else {
      session.refs.banner?.classList.add('hidden');
    }

    if (doc.head) {
      const style = doc.createElement('style');
      style.textContent = `
        [data-ppt-vis-selected="1"] {
          outline: 2px solid #3b82f6 !important;
          outline-offset: 2px !important;
        }
        [contenteditable="true"] {
          outline: 2px dashed #3b82f6 !important;
          outline-offset: 2px !important;
          cursor: text !important;
        }
      `;
      doc.head.appendChild(style);
    }

    this._syncInspector(session);
    if (!session.readOnly) this._bindCanvas(session);
  },

  _bindCanvas(session) {
    const doc = session.doc;
    if (!doc) return;

    const clickHandler = (e) => {
      if (session.editingEl) return; // clicks inside the text being edited pass through
      const target = this._findTarget(doc, e.target);
      if (!target) {
        this._select(session, null);
        return;
      }
      e.preventDefault();
      e.stopPropagation();
      this._select(session, target);
    };

    const dblclickHandler = (e) => {
      const target = this._findTarget(doc, e.target);
      if (!target) return;
      const tag = target.tagName.toUpperCase();
      if (['IMG', 'BR', 'HR', 'INPUT', 'TEXTAREA', 'SELECT', 'CANVAS', 'SVG', 'VIDEO', 'IFRAME'].includes(tag)) return;
      e.preventDefault();
      e.stopPropagation();
      this._select(session, target);
      this._startTextEdit(session, target);
    };

    const mousedownHandler = (e) => {
      if (e.button !== 0 || session.editingEl) return;
      const target = this._findTarget(doc, e.target);
      if (!target) return;
      e.preventDefault();
      e.stopPropagation();
      this._select(session, target);
      session.dragging = true;
      session.moved = false;
      session.dragStartX = e.clientX;
      session.dragStartY = e.clientY;
      session.startLeft = parseFloat(target.style.left) || 0;
      session.startTop = parseFloat(target.style.top) || 0;
      if (doc.body) doc.body.style.userSelect = 'none';
    };

    const mousemoveHandler = (e) => {
      if (!session.dragging || !session.selectedEl) return;
      e.preventDefault();
      const dx = e.clientX - session.dragStartX;
      const dy = e.clientY - session.dragStartY;
      if (dx !== 0 || dy !== 0) session.moved = true;
      session.selectedEl.style.left = `${Math.round(session.startLeft + dx)}px`;
      session.selectedEl.style.top = `${Math.round(session.startTop + dy)}px`;
      this._syncInspector(session);
    };

    const mouseupHandler = () => {
      if (!session.dragging) return;
      session.dragging = false;
      if (doc.body) doc.body.style.userSelect = '';
      this._syncInspector(session);
      if (session.moved && session.selectedEl) {
        this._commitPosition(session, session.selectedEl);
      }
      session.moved = false;
    };

    const keydownHandler = (e) => {
      if (session.editingEl) {
        if (e.key === 'Escape') {
          e.preventDefault();
          e.stopPropagation();
          this._endTextEdit(session, false);
        }
        return;
      }
      if (!session.selectedEl) return;
      const step = e.shiftKey ? 10 : 1;
      if (e.key === 'ArrowLeft' || e.key === 'ArrowRight' || e.key === 'ArrowUp' || e.key === 'ArrowDown') {
        e.preventDefault();
        e.stopPropagation();
        const dx = e.key === 'ArrowLeft' ? -step : e.key === 'ArrowRight' ? step : 0;
        const dy = e.key === 'ArrowUp' ? -step : e.key === 'ArrowDown' ? step : 0;
        this._nudge(session, dx, dy);
      } else if (e.key === 'Delete' || e.key === 'Backspace') {
        e.preventDefault();
        e.stopPropagation();
        this.removeSelected(session);
      } else if (e.key === 'Escape') {
        e.preventDefault();
        this._select(session, null);
      }
    };

    doc.addEventListener('click', clickHandler, true);
    doc.addEventListener('dblclick', dblclickHandler, true);
    doc.addEventListener('mousedown', mousedownHandler, true);
    doc.addEventListener('mousemove', mousemoveHandler, true);
    doc.addEventListener('mouseup', mouseupHandler, true);
    doc.addEventListener('keydown', keydownHandler, true);

    session.handlers = { click: clickHandler, dblclick: dblclickHandler, mousedown: mousedownHandler, mousemove: mousemoveHandler, mouseup: mouseupHandler, keydown: keydownHandler };
  },

  _findTarget(doc, eventTarget) {
    let el = eventTarget;
    while (el && el !== doc.documentElement) {
      if (this._isEditableElement(el)) return el;
      el = el.parentElement;
    }
    return null;
  },

  _isEditableElement(el) {
    if (!el || !el.tagName) return false;
    const tag = el.tagName.toUpperCase();
    return !['HTML', 'BODY', 'HEAD', 'META', 'TITLE', 'LINK', 'STYLE', 'SCRIPT', 'BASE'].includes(tag);
  },

  _select(session, el) {
    if (session.editingEl && session.editingEl !== el) {
      this._endTextEdit(session, true);
    }
    if (session.selectedEl && session.selectedEl !== el) {
      session.selectedEl.removeAttribute('data-ppt-vis-selected');
    }
    session.selectedEl = el || null;
    if (el) el.setAttribute('data-ppt-vis-selected', '1');
    this._syncInspector(session);
  },

  // ---------- text editing ----------

  _startTextEdit(session, el) {
    this._endTextEdit(session, true);
    session.editingEl = el;
    session.editingOriginalHtml = el.innerHTML;
    el.setAttribute('contenteditable', 'true');
    el.focus();
    el.addEventListener('blur', () => this._endTextEdit(session, true), { once: true });
  },

  _endTextEdit(session, commit) {
    const el = session.editingEl;
    if (!el) return;
    session.editingEl = null;
    el.removeAttribute('contenteditable');
    if (!commit) {
      el.innerHTML = session.editingOriginalHtml;
      return;
    }
    if (el.innerHTML !== session.editingOriginalHtml) {
      this._commit(session, { type: 'html', path: this.buildElementPath(el), html: el.innerHTML });
    }
  },

  // ---------- ops commit ----------

  _commit(session, op) {
    this._commitMany(session, [op]);
  },

  _commitMany(session, ops) {
    if (session.readOnly || this.session !== session) return;
    for (const op of ops) {
      session.ops = this.mergeOp(session.ops, op);
    }
    const result = this.replayOps(session.baseHtml, session.ops);
    if (typeof session.onCommit === 'function') {
      session.onCommit(result.html, result.failed);
    }
    this._syncUndoState(session);
  },

  _commitPosition(session, el) {
    const ops = [];
    const computed = el.ownerDocument.defaultView.getComputedStyle(el);
    if (computed.position === 'static') {
      el.style.position = 'relative';
      ops.push({ type: 'style', path: this.buildElementPath(el), name: 'position', value: 'relative' });
    }
    const path = this.buildElementPath(el);
    ops.push({ type: 'style', path, name: 'left', value: el.style.left });
    ops.push({ type: 'style', path, name: 'top', value: el.style.top });
    this._commitMany(session, ops);
  },

  _nudge(session, dx, dy) {
    const el = session.selectedEl;
    if (!el) return;
    el.style.left = `${(parseFloat(el.style.left) || 0) + dx}px`;
    el.style.top = `${(parseFloat(el.style.top) || 0) + dy}px`;
    this._syncInspector(session);
    this._commitPosition(session, el);
  },

  removeSelected(session) {
    const el = session.selectedEl;
    if (!el || session.readOnly) return;
    const path = this.buildElementPath(el);
    if (session.editingEl === el) session.editingEl = null;
    session.selectedEl = null;
    el.parentNode.removeChild(el);
    this._syncInspector(session);
    this._commit(session, { type: 'remove', path });
  },

  undo(session) {
    if (!session || session.readOnly || session.ops.length === 0) return;
    session.ops = session.ops.slice(0, -1);
    const result = this.replayOps(session.baseHtml, session.ops);
    if (typeof session.onCommit === 'function') {
      session.onCommit(result.html, result.failed);
    }
    this._syncUndoState(session);
    this._loadLive(session, result.html);
  },

  // ---------- toolbar actions ----------

  _insertSnippet(session, html) {
    const doc = session.doc;
    if (!doc || !doc.body) return;
    const selected = session.selectedEl;
    const parent = selected && selected.parentElement
      ? selected.parentElement
      : (doc.querySelector('.slide') || doc.body);
    const index = selected && selected.parentElement === parent
      ? Array.prototype.indexOf.call(parent.children, selected) + 1
      : parent.children.length;
    const tpl = doc.createElement('template');
    tpl.innerHTML = html;
    const node = tpl.content.firstElementChild;
    if (!node) return;
    parent.insertBefore(node, parent.children[index] || null);
    this._commit(session, {
      type: 'insert',
      parentPath: parent === doc.body ? '' : this.buildElementPath(parent),
      index,
      html,
    });
    this._select(session, node);
  },

  insertTextBox(session) {
    if (!session || session.readOnly) return;
    this._insertSnippet(session, '<div style="position:absolute;left:38%;top:44%;font-size:28px;line-height:1.5;">双击编辑文本</div>');
  },

  async insertImage(session) {
    if (!session || session.readOnly) return;
    if (!window.__TAURI__) {
      this._toast(session, '插入图片需要在桌面应用中使用', true);
      return;
    }
    try {
      const files = await window.__TAURI__.core.invoke('pick_files');
      const images = (files || []).filter(f => /\.(png|jpe?g|gif|svg|webp|bmp)$/i.test(f));
      if (images.length === 0) return;
      const imported = await window.__TAURI__.core.invoke('import_ppte_resources', {
        folderPath: session.folderPath,
        sourcePaths: [images[0]],
      });
      const rel = imported && imported[0] && imported[0].path;
      if (!rel) return;
      this._insertSnippet(session, `<img src="${rel}" style="max-width:60%;display:block;margin:24px auto;">`);
    } catch (e) {
      if (e !== 'cancelled') {
        console.error('Insert image failed:', e);
        this._toast(session, `插入图片失败：${e}`, true);
      }
    }
  },

  // ---------- inspector ----------

  _bindChrome(session) {
    const { addText, addImage, remove, undo, inputs } = session.refs;
    if (addText) addText.onclick = () => this.insertTextBox(session);
    if (addImage) addImage.onclick = () => this.insertImage(session);
    if (remove) remove.onclick = () => this.removeSelected(session);
    if (undo) undo.onclick = () => this.undo(session);

    const bindNumber = (input, name, ensurePositioned) => {
      if (!input) return;
      input.onchange = () => {
        const el = session.selectedEl;
        if (!el || session.syncing) return;
        const value = parseFloat(input.value);
        if (!Number.isFinite(value)) return;
        const ops = [];
        const path = this.buildElementPath(el);
        if (ensurePositioned) {
          const computed = el.ownerDocument.defaultView.getComputedStyle(el);
          if (computed.position === 'static') {
            el.style.position = 'relative';
            ops.push({ type: 'style', path, name: 'position', value: 'relative' });
          }
        }
        const finalValue = `${Math.max(name === 'left' || name === 'top' ? -99999 : 1, value)}px`;
        el.style.setProperty(name, finalValue);
        ops.push({ type: 'style', path, name, value: finalValue });
        this._commitMany(session, ops);
        this._syncInspector(session);
      };
    };
    bindNumber(inputs.left, 'left', true);
    bindNumber(inputs.top, 'top', true);
    bindNumber(inputs.width, 'width', false);
    bindNumber(inputs.height, 'height', false);
    bindNumber(inputs.fontSize, 'font-size', false);

    if (inputs.color) {
      inputs.color.oninput = () => {
        const el = session.selectedEl;
        if (!el || session.syncing) return;
        el.style.setProperty('color', inputs.color.value);
        this._commit(session, { type: 'style', path: this.buildElementPath(el), name: 'color', value: inputs.color.value });
      };
    }
    if (inputs.bold) {
      inputs.bold.onclick = () => {
        const el = session.selectedEl;
        if (!el) return;
        const computed = el.ownerDocument.defaultView.getComputedStyle(el);
        const isBold = parseInt(computed.fontWeight, 10) >= 600 || computed.fontWeight === 'bold';
        const value = isBold ? '400' : '700';
        el.style.setProperty('font-weight', value);
        this._commit(session, { type: 'style', path: this.buildElementPath(el), name: 'font-weight', value });
        this._syncInspector(session);
      };
    }
    if (inputs.align) {
      inputs.align.onchange = () => {
        const el = session.selectedEl;
        if (!el || session.syncing) return;
        const value = inputs.align.value;
        if (value) el.style.setProperty('text-align', value);
        else el.style.removeProperty('text-align');
        this._commit(session, { type: 'style', path: this.buildElementPath(el), name: 'text-align', value });
        this._syncInspector(session);
      };
    }
  },

  _syncInspector(session) {
    const { selectedLabel, inputs, remove } = session.refs;
    const el = session.selectedEl;
    if (remove) remove.disabled = session.readOnly || !el;
    if (!el) {
      if (selectedLabel) selectedLabel.textContent = '未选择';
      session.syncing = true;
      ['left', 'top', 'width', 'height', 'fontSize'].forEach(k => { if (inputs[k]) inputs[k].value = ''; });
      if (inputs.align) inputs.align.value = '';
      if (inputs.bold) inputs.bold.classList.remove('active');
      session.syncing = false;
      return;
    }
    const win = el.ownerDocument.defaultView;
    const computed = win.getComputedStyle(el);
    const name = `${el.tagName.toLowerCase()}${el.id ? `#${el.id}` : ''}${el.className && typeof el.className === 'string' && el.className.trim() ? '.' + el.className.trim().replace(/\s+/g, '.') : ''}`;
    if (selectedLabel) selectedLabel.textContent = name;

    session.syncing = true;
    if (inputs.left) inputs.left.value = Math.round(parseFloat(el.style.left) || 0);
    if (inputs.top) inputs.top.value = Math.round(parseFloat(el.style.top) || 0);
    if (inputs.width) inputs.width.value = Math.round(parseFloat(el.style.width) || parseFloat(computed.width) || 0);
    if (inputs.height) inputs.height.value = Math.round(parseFloat(el.style.height) || parseFloat(computed.height) || 0);
    if (inputs.fontSize) inputs.fontSize.value = Math.round(parseFloat(el.style.fontSize) || parseFloat(computed.fontSize) || 0);
    if (inputs.color) inputs.color.value = this._rgbToHex(computed.color);
    if (inputs.bold) {
      const weight = computed.fontWeight;
      inputs.bold.classList.toggle('active', parseInt(weight, 10) >= 600 || weight === 'bold');
    }
    if (inputs.align) {
      const align = el.style.textAlign || '';
      inputs.align.value = ['left', 'center', 'right'].includes(align) ? align : '';
    }
    session.syncing = false;
  },
};
